async function openManagedObject(row){
 state.selected={managedObject:row};state.tab='Placement';$('inspector').hidden=false;$('scrim').hidden=false;$('back-work').hidden=true;$('ancestry').replaceChildren();$('asset-title').textContent=row.title;$('asset-id').textContent=row.sha256;$('asset-badges').replaceChildren(node('span','badge','Byte object'),node('span','badge','Observed copies · not custody'));$('close').focus();
 try{const d=await api('/api/storage/objects',{project:managedObjects.project,sha:row.sha256,sort:'bytes'});if(state.selected?.managedObject!==row)return;if(Object.entries(d.snapshots).some(([id,sha])=>state.projects.find(p=>p.id===id)?.commit!==sha))throw Error('A project snapshot changed. Refresh the catalog.');state.selected.managedData=d;state.selected.fullObject=d.items[0];drawManagedObject();}catch(e){$('detail').replaceChildren(node('p','callout',e.message));}
}
